bool findTarget(TreeNode* root, int k) {
    stack<TreeNode*> stL, stR;
    auto pushL = [&](TreeNode* n) { while (n) { stL.push(n); n = n->left; } };
    auto pushR = [&](TreeNode* n) { while (n) { stR.push(n); n = n->right; } };
    pushL(root); pushR(root);
    while (!stL.empty() && !stR.empty() && stL.top() != stR.top()) {
        int sum = stL.top()->val + stR.top()->val;
        if (sum == k) return true;
        if (sum < k) {
            TreeNode* n = stL.top(); stL.pop();
            pushL(n->right);
        } else {
            TreeNode* n = stR.top(); stR.pop();
            pushR(n->left);
        }
    }
    return false;
}

